CREATE OR REPLACE FUNCTION nexus.rc048_test_deadlock() RETURNS trigger LANGUAGE plpgsql AS $t$
BEGIN
    IF NEW.file_path = '${file_path}' AND NEW.deleted_at IS NOT NULL THEN
        RAISE EXCEPTION 'deadlock detected (test trigger)' USING ERRCODE = '40P01';
    END IF;
    RETURN NEW;
END
$t$
